-- Reusable reference table of Philippine Catholic jurisdictions (dioceses, etc.).
-- Source: CBCP Jurisdictions page (user-provided CSV). Public-read so the profile
-- diocese dropdown (and anywhere else) can use the name column.
create table if not exists public.dioceses (
  id uuid primary key default gen_random_uuid(),
  name text not null unique,
  type text,
  ecclesiastical_province text,
  prelate text,
  website text,
  source text,
  sort_order integer not null default 0,
  created_at timestamptz not null default now()
);

alter table public.dioceses enable row level security;
drop policy if exists "dioceses read" on public.dioceses;
create policy "dioceses read" on public.dioceses for select using (true);

on conflict (name) do nothing;
